document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector(".greedy-nav"),t=e?.querySelector(".visible-links"),n=e?.querySelector(".hidden-links"),i=e?.querySelector("button");if(!e||!t||!n||!i)return;const o=()=>{i.classList.remove("close"),n.classList.add("hidden"),i.setAttribute("aria-expanded","false")};i.setAttribute("aria-expanded","false"),i.addEventListener("click",e=>{e.stopPropagation();const t=n.classList.toggle("hidden");i.classList.toggle("close",!t),i.setAttribute("aria-expanded",String(!t))}),document.addEventListener("click",e=>{n.contains(e.target)||i.contains(e.target)||o()}),window.addEventListener("resize",o)});